package com.bank.core.analysis;

// Evidence for the split decision — NOT a gut feeling.
public class ModuleMetrics {
    private final String name;
    private final double changeCouplingWithCore; // 0..1, how often it co-changes with core
    private final boolean ownershipClear;        // is there a single owning team?
    private final boolean canStarveOthers;       // blast radius inside the monolith
    private final boolean needsIndependentScale;

    public ModuleMetrics(String name, double coupling, boolean owner,
                         boolean starve, boolean scale) {
        this.name = name; this.changeCouplingWithCore = coupling;
        this.ownershipClear = owner; this.canStarveOthers = starve;
        this.needsIndependentScale = scale;
    }
    public String name() { return name; }
    public double coupling() { return changeCouplingWithCore; }
    public boolean ownershipClear() { return ownershipClear; }
    public boolean canStarveOthers() { return canStarveOthers; }
    public boolean needsIndependentScale() { return needsIndependentScale; }
}
