package com.bank.core.analysis;

import java.util.logging.Logger;

// Recommends split / keep based on evidence, applying the real-world rules.
public class SplitAdvisor {
    private static final Logger log = Logger.getLogger(SplitAdvisor.class.getName());
    private final double couplingThreshold;
    public SplitAdvisor(double couplingThreshold) { this.couplingThreshold = couplingThreshold; }

    public String recommend(ModuleMetrics m) {
        // Rule 1: high co-change with core → splitting spreads one change across two services.
        if (m.coupling() >= couplingThreshold) {
            log.info(() -> "KEEP " + m.name() + " (co-changes with core " + m.coupling() + ")");
            return "KEEP_IN_MONOLITH";
        }
        // Rule 2: unclear ownership → split creates an orphan service.
        if (!m.ownershipClear()) {
            log.warning(() -> "KEEP " + m.name() + " (no clear owner — would become an orphan)");
            return "KEEP_FIX_OWNERSHIP_FIRST";
        }
        // Rule 3: independent change + clear owner + (blast radius OR scaling need) → split.
        if (m.canStarveOthers() || m.needsIndependentScale()) {
            log.info(() -> "SPLIT " + m.name() + " (independent + fault/scale need)");
            return "EXTRACT_TO_SERVICE";
        }
        // Default: strengthen internal boundary instead of paying the network tax.
        log.info(() -> "BOUNDARY " + m.name() + " (modularize internally, do not split yet)");
        return "STRENGTHEN_INTERNAL_BOUNDARY";
    }
}
