package com.bank.core;

import com.bank.core.analysis.ModuleMetrics;
import com.bank.core.analysis.SplitAdvisor;
import java.util.List;
import java.util.logging.*;

public class SplitDecisionDemo {
    private static final Logger log = Logger.getLogger(SplitDecisionDemo.class.getName());
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h); log.setLevel(Level.ALL);
    }
    public static void main(String[] args) {
        SplitAdvisor advisor = new SplitAdvisor(0.6);

        // Evidence gathered from commit history + ops data for the 300K-line monolith.
        List<ModuleMetrics> modules = List.of(
            // account & transfer co-change a lot → keep together
            new ModuleMetrics("transfers", 0.82, true, false, false),
            new ModuleMetrics("accounts",  0.80, true, false, false),
            // reporting: independent cadence, clear compliance owner, starves others → SPLIT
            new ModuleMetrics("reporting", 0.15, true, true, true),
            // loan-origination: independent but no clear owner → fix ownership first
            new ModuleMetrics("loan-origination", 0.25, false, false, true)
        );

        log.info("=== Split decision for 300K-line core-banking monolith ===");
        for (ModuleMetrics m : modules) {
            String decision = advisor.recommend(m);
            log.info(() -> "  → " + m.name() + ": " + decision);
        }
        log.info("Conclusion: extract 'reporting' only; modularize the rest internally");
    }
}

